[[noreturn]] void fail(const char* message){throw std::runtime_error(message);}
QString qs(const fs::path& p){return QString::fromStdWString(p.wstring());}
QString qstr(const std::string& s){return QString::fromUtf8(s.data(),qsizetype(s.size()));}
bool optional(const QJsonObject& o,const char* k){return !o.contains(k)||o.value(k).isNull();}
QJsonObject object(const QJsonValue& v){if(!v.isObject())fail("必需的对象缺失或格式错误");return v.toObject();}
QJsonArray array(const QJsonValue& v){if(!v.isArray())fail("必需的数组缺失或格式错误");return v.toArray();}
QString string(const QJsonValue& v){if(!v.isString())fail("必需的字符串缺失或格式错误");return v.toString();}
bool boolean(const QJsonValue& v){if(!v.isBool())fail("必需的布尔值缺失或格式错误");return v.toBool();}
double number(const QJsonValue& v){if(!v.isDouble()||!std::isfinite(v.toDouble()))fail("必需的有限数值缺失或格式错误");return v.toDouble();}
double bounded(const QJsonValue& v,double lo,double hi){auto n=number(v);if(n<lo||n>hi)fail("数值设置超出支持范围");return n;}
int integer(const QJsonValue& v,int lo,int hi){auto n=bounded(v,lo,hi);if(std::trunc(n)!=n)fail("应为整数");return int(n);}
QString uuid(const QJsonValue& value){auto s=string(value);QUuid id(s);if(s.size()!=36||s[8]!='-'||s[13]!='-'||s[18]!='-'||s[23]!='-')fail("无效的 UUID");auto normalized=id.toString(QUuid::WithoutBraces).toUpper();if(normalized.compare(s,Qt::CaseInsensitive)!=0)fail("无效的 UUID");return normalized;}
std::string optionalId(const QJsonObject&o,const char*k){return optional(o,k)?std::string{}:uuid(o[k]).toStdString();}
bool optionalBool(const QJsonObject&o,const char*k,bool fallback){return optional(o,k)?fallback:boolean(o[k]);}
