void enumValue(const QJsonValue&v,std::initializer_list<const char*> values){auto s=string(v);if(std::none_of(values.begin(),values.end(),[&](const char*p){return s==p;}))fail("未知枚举值");}
Transform transform(const QJsonValue&value){auto o=object(value);auto origin=array(o["origin"]),size=array(o["size"]);if(origin.size()!=2||size.size()!=2)fail("基础几何需要双数字数组");Transform t;
    t.x=number(origin[0]);t.y=number(origin[1]);t.width=number(size[0]);t.height=number(size[1]);t.rotation=number(o["rotation"]);t.flipX=boolean(o["flipX"]);t.flipY=boolean(o["flipY"]);
    auto sampling=string(o["sampling"]);if(sampling=="Nearest"||sampling=="邻近")t.sampling=Transform::Sampling::Nearest;else if(sampling=="Smooth"||sampling=="平滑")t.sampling=Transform::Sampling::Smooth;else if(sampling=="High quality"||sampling=="高质量")t.sampling=Transform::Sampling::High;else fail("未知采样值");if(!t.valid())fail("无效的图层变换");return t;}
QJsonObject encodeTransform(const Transform&t){return {{"origin",QJsonArray{t.x,t.y}},{"size",QJsonArray{t.width,t.height}},{"rotation",t.rotation},{"flipX",t.flipX},{"flipY",t.flipY},{"sampling",t.sampling==Transform::Sampling::Nearest?"Nearest":t.sampling==Transform::Sampling::Smooth?"Smooth":"High quality"}};}
void channel(const QJsonValue& v){enumValue(v,{"RGB","Red","Green","Blue","红色","绿色","蓝色"});}
void rangeName(const QJsonValue&v){enumValue(v,{"Master","Reds","Yellows","Greens","Cyans","Blues","Magentas","主","红色","黄色","绿色","青色","蓝色","洋红"});}
void hsvTriplet(const QJsonObject&o){bounded(o["hue"],-360,360);bounded(o["saturation"],-100,100);bounded(o["lightness"],-100,100);}
void color(const QJsonValue&v){auto o=object(v);for(const char*k:{"red","green","blue"})bounded(o[k],0,1);}
void validateAdjustment(const QJsonObject&o){
    enumValue(o["kind"],{"Hue/Saturation","Levels","Curves","Exposure","Gradient Map","Grain","Invert","Black & White","Color Balance","Gaussian Blur","Motion Blur","Add Noise","色阶","曲线","曝光","渐变映射","颗粒","反相","黑白","色彩平衡","高斯模糊","动感模糊","添加杂色"});hsvTriplet(o);boolean(o["colorize"]);
    auto levels=object(o["levels"]);channel(levels["channel"]);auto ranges=array(levels["ranges"]);if(ranges.size()!=4)fail("色阶需要四个范围");
    for(auto v:ranges){auto r=object(v);auto black=bounded(r["black"],0,254);bounded(r["white"],black+1,255);bounded(r["gamma"],.1,9.99);bounded(r["outputBlack"],0,255);bounded(r["outputWhite"],0,255);}
    auto curves=object(o["curves"]);channel(curves["channel"]);auto channels=array(curves["channels"]);if(channels.size()!=4)fail("曲线需要四个通道");
    for(auto v:channels){auto points=array(v);if(points.size()<2||points.size()>32)fail("曲线点数无效");double last=-1;for(qsizetype i=0;i<points.size();++i){auto p=object(points[i]);auto x=bounded(p["x"],0,255);bounded(p["y"],0,255);if(x<=last||(i==0&&x!=0)||(i==points.size()-1&&x!=255))fail("曲线横坐标无效");last=x;}}
    if(!optional(o,"hsvSettings")){auto h=object(o["hsvSettings"]);rangeName(h["range"]);boolean(h["colorize"]);boolean(h["invertRange"]);
        for(const char*k:{"adjustments","bands"}){auto pairs=array(h[k]);if(pairs.size()%2)fail("枚举字典必须包含键/值对");for(qsizetype i=0;i<pairs.size();i+=2){rangeName(pairs[i]);auto v=object(pairs[i+1]);if(std::string(k)=="adjustments")hsvTriplet(v);else for(const char*field:{"falloffStart","rangeStart","rangeEnd","falloffEnd"})number(v[field]);}}}
    if(!optional(o,"exposureSettings")){auto e=object(o["exposureSettings"]);bounded(e["exposure"],-20,20);bounded(e["offset"],-.5,.5);bounded(e["gamma"],.01,9.99);}
    if(!optional(o,"gradientMapSettings")){auto g=object(o["gradientMapSettings"]);color(g["shadows"]);color(g["highlights"]);boolean(g["reversed"]);}
    if(!optional(o,"grainSettings")){auto g=object(o["grainSettings"]);bounded(g["amount"],0,100);bounded(g["size"],.5,20);bounded(g["roughness"],0,100);auto seed=bounded(g["seed"],0,4294967295.);if(std::trunc(seed)!=seed)fail("颗粒种子必须为 UInt32");}
    if(!optional(o,"blackWhiteSettings")){auto g=object(o["blackWhiteSettings"]);for(const char*k:{"reds","yellows","greens","cyans","blues","magentas"})bounded(g[k],-200,300);}
    if(!optional(o,"colorBalanceSettings")){auto g=object(o["colorBalanceSettings"]);for(const char*tone:{"shadows","midtones","highlights"}){auto t=object(g[tone]);for(const char*k:{"cyanRed","magentaGreen","yellowBlue"})bounded(t[k],-100,100);}}
    if(!optional(o,"filterSettings")){auto g=object(o["filterSettings"]);bounded(g["radius"],0,250);bounded(g["angle"],-90,90);bounded(g["distance"],0,2000);bounded(g["amount"],0,400);boolean(g["gaussian"]);boolean(g["monochromatic"]);if(!optional(g,"seed")){auto seed=bounded(g["seed"],0,4294967295.);if(std::trunc(seed)!=seed)fail("噪点种子必须为 UInt32");}}
}
void validateShape(const QJsonObject&o,int version){enumValue(o["kind"],{"Rectangle","Ellipse","Line","矩形","椭圆","直线"});for(const char*k:{"red","green","blue","cornerRadius"})number(o[k]);if(string(o["kind"])=="Line"||string(o["kind"])=="直线"){bounded(o["lineWidth"],.1,500);for(const char*end:{"start","end"}){auto p=object(o[end]);bounded(p["x"],0,1);bounded(p["y"],0,1);}}if(!optional(o,"stroke")){if(version<14)fail("形状描边需要 v14 格式");if(string(o["kind"])=="Line"||string(o["kind"])=="直线")fail("线条形状无法携带描边");auto s=object(o["stroke"]);bounded(s["width"],.1,500);for(const char*k:{"red","green","blue"})bounded(s[k],0,1);}}
Pixel colorPixel(const QJsonValue&v){auto o=object(v);auto ch=[](double x){return uint8_t(std::clamp(std::lround(x*255),0L,255L));};return {ch(bounded(o["red"],0,1)),ch(bounded(o["green"],0,1)),ch(bounded(o["blue"],0,1)),255};}
QJsonObject encodeColor(Pixel p){return {{"red",p.r/255.},{"green",p.g/255.},{"blue",p.b/255.}};}
Blend blendNamed(const QJsonValue&v){auto name=string(v);auto it=std::find_if(blendNames.begin(),blendNames.end(),[&](const char*n){return name==n;});if(it==blendNames.end())fail("未知混合模式");return Blend(it-blendNames.begin());}
void readShadow(const QJsonObject&o,EffectShadow&s){s.enabled=boolean(o["enabled"]);s.opacity=bounded(o["opacity"],0,1);s.angle=bounded(o["angle"],-360,360);s.distance=bounded(o["distance"],0,30000);s.size=bounded(o["size"],0,250);s.color=colorPixel(o["color"]);s.blend=blendNamed(o["blend"]);}
QJsonObject encodeShadow(const EffectShadow&s){return {{"enabled",s.enabled},{"opacity",s.opacity},{"angle",s.angle},{"distance",s.distance},{"size",s.size},{"color",encodeColor(s.color)},{"blend",blendNames.at(size_t(s.blend))}};}
void readGlow(const QJsonObject&o,EffectGlow&s){s.enabled=boolean(o["enabled"]);s.opacity=bounded(o["opacity"],0,1);s.size=bounded(o["size"],0,250);s.color=colorPixel(o["color"]);s.blend=blendNamed(o["blend"]);}
QJsonObject encodeGlow(const EffectGlow&s){return {{"enabled",s.enabled},{"opacity",s.opacity},{"size",s.size},{"color",encodeColor(s.color)},{"blend",blendNames.at(size_t(s.blend))}};}
void readEffects(const QJsonObject&o,LayerEffects&fx){fx.specified=true;if(!optional(o,"dropShadow"))readShadow(object(o["dropShadow"]),fx.dropShadow);if(!optional(o,"innerShadow"))readShadow(object(o["innerShadow"]),fx.innerShadow);if(!optional(o,"outerGlow"))readGlow(object(o["outerGlow"]),fx.outerGlow);if(!optional(o,"innerGlow"))readGlow(object(o["innerGlow"]),fx.innerGlow);if(!optional(o,"stroke")){auto s=object(o["stroke"]);fx.stroke.enabled=boolean(s["enabled"]);fx.stroke.size=bounded(s["size"],0,250);fx.stroke.color=colorPixel(s["color"]);fx.stroke.position=integer(s["position"],0,2);}if(!optional(o,"colorOverlay")){auto s=object(o["colorOverlay"]);fx.colorOverlay.enabled=boolean(s["enabled"]);fx.colorOverlay.opacity=bounded(s["opacity"],0,1);fx.colorOverlay.color=colorPixel(s["color"]);fx.colorOverlay.blend=blendNamed(s["blend"]);}}
QJsonObject encodeEffects(const LayerEffects&fx){QJsonObject o;if(fx.dropShadow.enabled||fx.dropShadow!=EffectShadow{})o["dropShadow"]=encodeShadow(fx.dropShadow);if(fx.innerShadow.enabled||fx.innerShadow!=EffectShadow{})o["innerShadow"]=encodeShadow(fx.innerShadow);if(fx.outerGlow.enabled||fx.outerGlow!=EffectGlow{})o["outerGlow"]=encodeGlow(fx.outerGlow);if(fx.innerGlow.enabled||fx.innerGlow!=EffectGlow{})o["innerGlow"]=encodeGlow(fx.innerGlow);if(fx.stroke.enabled||fx.stroke!=EffectStroke{})o["stroke"]=QJsonObject{{"enabled",fx.stroke.enabled},{"size",fx.stroke.size},{"color",encodeColor(fx.stroke.color)},{"position",fx.stroke.position}};if(fx.colorOverlay.enabled||fx.colorOverlay!=EffectOverlay{})o["colorOverlay"]=QJsonObject{{"enabled",fx.colorOverlay.enabled},{"opacity",fx.colorOverlay.opacity},{"color",encodeColor(fx.colorOverlay.color)},{"blend",blendNames.at(size_t(fx.colorOverlay.blend))}};return o;}
bool regularStyle(const std::string& style){return style.empty()||style=="Regular"||style=="常规"||style=="Normal";}
bool textUsesExtended(const TextContent& text){if(text.alignment!=TextAlignment::Left||text.boxWidth||text.boxHeight||text.tracking!=0||text.leading!=0||!regularStyle(text.fontStyle))return true;for(const auto& run:text.fontRuns)if(!regularStyle(run.fontStyle))return true;return false;}
TextRun readRun(const QJsonObject&o,int units,bool font,int version){TextRun run;run.location=integer(o["location"],0,units);run.length=integer(o["length"],0,units-run.location);if(!font){run.hasColor=true;run.red=bounded(o["red"],0,1);run.green=bounded(o["green"],0,1);run.blue=bounded(o["blue"],0,1);}else{run.hasFont=true;run.fontFamily=string(o["fontFamily"]).toUtf8().toStdString();if(run.fontFamily.empty()||run.fontFamily.size()>256)fail("无效的字体文本段");run.fontSize=bounded(o["fontSize"],1,1000);if(!optional(o,"fontStyle")){if(version<12)fail("字体样式需要格式 v12");run.fontStyle=string(o["fontStyle"]).toUtf8().toStdString();if(run.fontStyle.empty()||run.fontStyle.size()>256)fail("无效的字体样式");}}return run;}
std::vector<TextRun> readRuns(const QJsonObject&o,const char*key,int units,bool font,int version){std::vector<TextRun> runs;if(optional(o,key))return runs;auto values=array(o[key]);if(values.size()>256)fail("文本运行过多");for(auto value:values)runs.push_back(readRun(object(value),units,font,version));return runs;}
QJsonObject parseJson(const QByteArray&bytes){QJsonParseError error;auto json=QJsonDocument::fromJson(bytes,&error);if(error.error!=QJsonParseError::NoError||!json.isObject())fail("无效的 JSON 对象");return json.object();}
int formatVersion(const Document&d){int version=7;if(!d.guides.empty())version=8;for(const auto&l:d.layers){if(l.deep)version=std::max(version,13);if(l.group&&l.opacity!=1)version=std::max(version,8);if(!l.adjustmentJson.empty()){auto kind=string(parseJson(QByteArray::fromStdString(l.adjustmentJson))["kind"]);if(kind=="Gaussian Blur"||kind=="Motion Blur"||kind=="Add Noise"||kind=="高斯模糊"||kind=="动感模糊"||kind=="添加杂色")version=std::max(version,9);}if(l.text){if(!l.text->colorRuns.empty())version=std::max(version,10);if(!l.text->fontRuns.empty())version=std::max(version,11);if(textUsesExtended(*l.text))version=std::max(version,12);}if(!l.shapeJson.empty()&&parseJson(QByteArray::fromStdString(l.shapeJson)).contains("stroke"))version=std::max(version,14);}return version;}
std::string jsonString(const QJsonObject&o){return QJsonDocument(o).toJson(QJsonDocument::Compact).toStdString();}
void noReparse(const fs::path&p){fs::path current;for(auto&part:fs::absolute(p).lexically_normal()){current/=part;if(current==current.root_name())continue;auto attributes=GetFileAttributesW(current.c_str());if(attributes==INVALID_FILE_ATTRIBUTES){auto error=GetLastError();if(error==ERROR_FILE_NOT_FOUND||error==ERROR_PATH_NOT_FOUND)continue;fail("无法检查项目路径");}if(attributes&FILE_ATTRIBUTE_REPARSE_POINT)fail("项目路径不能穿过重分析点");}}
void safeTree(const fs::path&p){noReparse(p);if(!fs::exists(p))return;if(!fs::is_directory(p))fail("应为项目包目录");for(auto&e:fs::recursive_directory_iterator(p)){noReparse(e.path());if(!e.is_regular_file()&&!e.is_directory())fail("不支持的包条目");}}
void removeTree(const fs::path&p){safeTree(p);if(fs::exists(p))fs::remove_all(p);}
QByteArray readFile(const fs::path&p,qint64 limit){noReparse(p);if(!fs::is_regular_file(p)||fs::file_size(p)>uintmax_t(limit))fail("项目文件缺失或过大");QFile file(qs(p));if(!file.open(QIODevice::ReadOnly))fail("无法读取项目文件");auto data=file.read(limit+1);if(data.size()>limit||file.error()!=QFileDevice::NoError)fail("项目文件读取失败");return data;}
void writeJson(const fs::path&p,const QJsonObject&o,qint64 limit=manifestLimit){auto bytes=QJsonDocument(o).toJson(QJsonDocument::Indented);if(bytes.size()>limit)fail("项目元数据超出大小限制");noReparse(p);QSaveFile file(qs(p));file.setDirectWriteFallback(false);if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())fail("无法提交项目元数据");}
fs::path normalize(const fs::path&p){auto path=fs::absolute(p).lexically_normal();if(path.filename().empty()||path==path.root_path())fail("无效的项目目标位置");noReparse(path);if(!fs::is_directory(path.parent_path()))fail("项目的父目录不存在");return path;}
fs::path suffix(const fs::path&p,const std::wstring&s){return p.parent_path()/(p.filename().wstring()+s);}
// A named mutex coordinates readers/writers without requiring write access merely to open
// a read-only package. Abandoned ownership is recoverable through the on-disk journal.
struct Lock {HANDLE handle{};explicit Lock(const fs::path&p){auto normalized=qs(p).toCaseFolded().toUtf8();uint64_t hash=14695981039346656037ull;for(char c:normalized){hash^=uint8_t(c);hash*=1099511628211ull;}auto name=L"Local\\CompositorProject-"+std::to_wstring(hash);handle=CreateMutexW(nullptr,FALSE,name.c_str());if(!handle)fail("无法创建项目协调互斥体");auto result=WaitForSingleObject(handle,0);if(result!=WAIT_OBJECT_0&&result!=WAIT_ABANDONED){CloseHandle(handle);handle=nullptr;fail("项目正被另一进程占用");}}~Lock(){if(handle){ReleaseMutex(handle);CloseHandle(handle);}}Lock(const Lock&)=delete;};
